            return {k: v for k, v in rows.items() if k not in cols}
        return [{k: v for k, v in r.items() if k not in cols} for r in rows]
    if name == "where":
        cond = cmd[len("where"):].strip()
        return [r for r in materialize(inp) if truthy(eval_where(cond, r, env))]
