        key = parse_words(cmd[len("sort-by"):].strip())[0]
        return sorted(materialize(inp), key=lambda r: r.get(key, ""))
    if name == "into" and len(words) > 1:
        if words[1] == "string":
            return into_string(inp, cmd)
        if words[1] in ("int", "integer"):
            return int(float(inp))
        if words[1] == "float":
            return float(inp)
    if name == "describe":
        return describe(inp)
    if name == "save":
        path = strip_quotes(words[-1])

