def simple_grid(headers, rows, show_header=True):
    if not rows and not headers:
        return ""
    cols = len(rows[0]) if rows else len(headers[0])
    widths = []
    for i in range(cols):
        vals = [str(r[i]) for r in rows]
        if show_header:
            vals += [str(headers[0][i])]
        widths.append(max(1, *(len(x) for x in vals)))
    def border(l, m, r):
        return l + m.join("─" * (w + 2) for w in widths) + r
    out = [border("╭", "┬", "╮")]
